{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Check and confirm pickup arrangement for the day",
        "actor": "Mother",
        "system": "Shared family calendar",
        "inputs": ["Scheduled childcare afternoon", "Current family availability"],
        "outputs": ["Confirmed pickup person for the day"]
      },
      {
        "id": "A2",
        "name": "Verify collector is on provider's authorised pickup list",
        "actor": "Mother",
        "system": "Childcare messaging app",
        "inputs": ["Confirmed pickup person", "Provider's authorised pickup list"],
        "outputs": ["Confirmation that collector is authorised, or identification of need to update list"]
      },
      {
        "id": "A3",
        "name": "Request authorised pickup list update from teacher",
        "actor": "Mother",
        "system": "Childcare messaging app",
        "inputs": ["Name of new or substitute collector"],
        "outputs": ["Update request sent to teacher"]
      },
      {
        "id": "A4",
        "name": "Teacher updates authorised pickup list",
        "actor": "Teacher (childcare provider)",
        "system": "Provider's internal system (unspecified)",
        "inputs": ["Update request from mother"],
        "outputs": ["Updated authorised pickup list", "Acknowledgement sent to mother"]
      },
      {
        "id": "A5",
        "name": "Notify collector of pickup responsibility",
        "actor": "Mother",
        "system": "Unspecified (general confirmation channel)",
        "inputs": ["Confirmed pickup person", "Pickup time and location details"],
        "outputs": ["Collector availability confirmed"]
      },
      {
        "id": "A6",
        "name": "Request same-day pickup change from teacher",
        "actor": "Mother",
        "system": "Childcare messaging app",
        "inputs": ["New collector details", "Reason for change"],
        "outputs": ["Change request sent to teacher"]
      },
      {
        "id": "A7",
        "name": "Teacher acknowledges same-day pickup change",
        "actor": "Teacher (childcare provider)",
        "system": "Childcare messaging app",
        "inputs": ["Change request from mother"],
        "outputs": ["Acknowledgement of change", "Updated authorised collector for that day"]
      },
      {
        "id": "A8",
        "name": "Collector performs child pickup",
        "actor": "Authorised collector (partner or backup caregiver)",
        "system": "None",
        "inputs": ["Authorised pickup status", "Teacher acknowledgement (if change occurred)"],
        "outputs": ["Child collected from provider"]
      },
      {
        "id": "A9",
        "name": "Record home arrival in family handover log",
        "actor": "Partner (collector)",
        "system": "Family handover log",
        "inputs": ["Child's arrival at home"],
        "outputs": ["Home arrival note logged with timestamp"]
      },
      {
        "id": "A10",
        "name": "Check family handover log for arrival confirmation",
        "actor": "Mother",
        "system": "Family handover log",
        "inputs": ["Expected end of pickup window"],
        "outputs": ["Confirmation of safe arrival, or identification of missing log entry"]
      },
      {
        "id": "A11",
        "name": "Escalate: contact collector and teacher",
        "actor": "Mother",
        "system": "Childcare messaging app / unspecified contact channel",
        "inputs": ["Missing or overdue home arrival log entry"],
        "outputs": ["Escalation contacts notified", "Resolution status pending"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Is the intended collector already on the provider's authorised pickup list?",
        "branches": [
          "Yes — proceed to notify collector (A5)",
          "No — request list update from teacher (A3)"
        ]
      },
      {
        "id": "D2",
        "condition": "Has the pickup arrangement changed during the day?",
        "branches": [
          "No change — collector proceeds to pickup (A8)",
          "Change required — request same-day change from teacher (A6)"
        ]
      },
      {
        "id": "D3",
        "condition": "Has teacher acknowledged the same-day pickup change?",
        "branches": [
          "Acknowledged — collector proceeds to pickup (A8)",
          "Not yet acknowledged — collection cannot proceed; mother waits or follows up"
        ]
      },
      {
        "id": "D4",
        "condition": "Has a home arrival note been logged in the family handover log by end of pickup window?",
        "branches": [
          "Yes — workflow complete",
          "No — escalate by contacting collector and teacher (A11)"
        ]
      }
    ],
    "exceptions": [
      {
        "id": "E1",
        "description": "Same-day pickup change requested but teacher acknowledgement not received before pickup time",
        "handling": "Collection cannot proceed until acknowledgement is received; mother must follow up with teacher via childcare messaging app"
      },
      {
        "id": "E2",
        "description": "Home arrival not logged by end of pickup window",
        "handling": "Mother contacts both the collector and the teacher to establish child's status; resolution path beyond initial escalation is not specified"
      },
      {
        "id": "E3",
        "description": "Intended collector is unavailable and a substitute is needed",
        "handling": "Mother identifies backup caregiver, requests authorised pickup list update from teacher, and notifies new collector; who physically takes over if no authorised person is available is not specified"
      }
    ],
    "dependencies": [
      {"from": "A1", "to": "A2", "type": "control_flow"},
      {"from": "A2", "to": "D1", "type": "control_flow"},
      {"from": "D1", "to": "A3", "type": "conditional"},
      {"from": "D1", "to": "A5", "type": "conditional"},
      {"from": "A3", "to": "A4", "type": "control_flow"},
      {"from": "A4", "to": "A5", "type": "control_flow"},
      {"from": "A5", "to": "D2", "type": "control_flow"},
      {"from": "D2", "to": "A6", "type": "conditional"},
      {"from": "D2", "to": "A8", "type": "conditional"},
      {"from": "A6", "to": "A7", "type": "control_flow"},
      {"from": "A7", "to": "D3", "type": "control_flow"},
      {"from": "D3", "to": "A8", "type": "conditional"},
      {"from": "A8", "to": "A9", "type": "control_flow"},
      {"from": "A9", "to": "A10", "type": "control_flow"},
      {"from": "A10", "to": "D4", "type": "control_flow"},
      {"from": "D4", "to": "A11", "type": "conditional"}
    ]
  },
  "automation_opportunities": [
    {
      "target": "A2 — Verify collector is on provider's authorised pickup list",
      "rationale": "If the provider's authorised pickup list were accessible via the childcare messaging app or a shared interface, the mother could receive an automated status check rather than manually verifying each day",
      "required_data": ["Current authorised pickup list from provider", "Identity of intended collector"],
      "constraints": ["Provider controls list updates; mother cannot update directly", "Requires provider system to expose list status in a readable form"],
      "confidence": "low"
    },
    {
      "target": "A5 — Notify collector of pickup responsibility",
      "rationale": "A recurring or templated notification to the confirmed collector could be triggered automatically from the shared family calendar when a pickup day is confirmed, reducing manual coordination",
      "required_data": ["Scheduled childcare afternoons from family calendar", "Collector contact details", "Pickup time and location"],
      "constraints": ["Notification channel to collector is currently unspecified", "Manual override needed when arrangement changes"],
      "confidence": "medium"
    },
    {
      "target": "A10 — Check family handover log for arrival confirmation",
      "rationale": "An automated alert to the mother could be triggered if no home arrival entry is logged in the family handover log by the end of the defined pickup window, removing the need for manual checking",
      "required_data": ["Pickup window end time", "Family handover log entry status"],
      "constraints": ["Pickup window end time must be explicitly defined and consistently recorded", "Family handover log must support time-based querying or notifications"],
      "confidence": "high"
    },
    {
      "target": "D2 — Has the pickup arrangement changed during the day?",
      "rationale": "Changes to the shared family calendar during the day could automatically flag a potential pickup change and prompt the mother to initiate a teacher notification, reducing the risk of a change being missed",
      "required_data": ["Real-time updates from shared family calendar", "Baseline pickup arrangement for the day"],
      "constraints": ["Requires calendar system to detect and surface same-day edits", "Mother must still manually contact teacher via childcare messaging app as acknowledgement is required"],
      "confidence": "medium"
    },
    {
      "target": "A6 and A7 — Request and acknowledge same-day pickup change",
      "rationale": "A structured in-app change request flow within the childcare messaging app could formalise the request-acknowledgement exchange, creating an auditable record and reducing ambiguity about whether acknowledgement was received",
      "required_data": ["New collector name and authorisation status", "Timestamp of request", "Timestamp of teacher acknowledgement"],
      "constraints": ["Depends on childcare messaging app supporting structured request workflows", "Teacher must actively respond within the app for acknowledgement to be recorded"],
      "confidence": "medium"
    }
  ],
  "remaining_gaps": [
    {
      "id": "G1",
      "description": "The specific channel used by the mother to notify the collector of their pickup responsibility is not specified; it is unclear whether this is a phone call, message, or calendar notification"
    },
    {
      "id": "G2",
      "description": "The form of teacher acknowledgement for a same-day pickup change is not specified; it is unknown whether a phone call, in-app message, or written note is required or sufficient"
    },
    {
      "id": "G3",
      "description": "The definition of the pickup window end time is not specified; it is unclear how long after the scheduled pickup time the mother waits before treating the absence of a log entry as an exception"
    },
    {
      "id": "G4",
      "description": "Who physically takes over collection if neither the partner nor the backup caregiver is available and no authorised collector can be reached is not specified"
    },
    {
      "id": "G5",
      "description": "The resolution path after the mother escalates to the collector and teacher in exception scenario E2 is not specified; it is unknown what steps follow if neither can be reached"
    },
    {
      "id": "G6",
      "description": "The frequency with which the pickup arrangement changes versus stays the same across a typical week is not known, making it difficult to assess the relative weight of the standard versus exception path"
    },
    {
      "id": "G7",
      "description": "The typical time of day when same-day changes occur is not specified, which limits the ability to design time-sensitive automation or alerting thresholds"
    },
    {
      "id": "G8",
      "description": "The system or format used by the provider to maintain the authorised pickup list is not specified; it is unknown whether it is digital, paper-based, or integrated with any app"
    }
  ]
}
